mapper.select:
select count(*)
from wxshop_order

    and user_id = #{userId}
    and is_pay = #{isPay}
    and is_taken = #{isTaken}
    and id = #{search}

select o.id, o.user_id, o.price, o.promotion, o.number, o.is_pay, o.is_taken,
o.comment, o.create_time, o.pay_time, o.taken_time,
ofd.id as ofd_id, ofd.order_id as ofd_order_id, ofd.food_id as ofd_food_id,
ofd.number as ofd_number, ofd.price as ofd_price, f.name as ofd_food_name
from wxshop_order o
inner join (
select id from wxshop_order

    and user_id = #{userId}
    and is_pay = #{isPay}
    and is_taken = #{isTaken}
    and id = #{search}

order by id desc
limit #{size} offset #{offset}
) tmp on o.id = tmp.id
left join wxshop_order_food ofd on o.id = ofd.order_id
left join wxshop_food f on f.id = ofd.food_id
order by o.id desc

select o.id, o.user_id, o.price, o.promotion, o.number, o.is_pay, o.is_taken, o.comment, o.create_time, o.pay_time, o.taken_time, ofd.id as ofd_id, ofd.order_id as ofd_order_id, ofd.food_id as ofd_food_id, ofd.number as ofd_number, ofd.price as ofd_price, f.name as ofd_food_name from wxshop_order o left join wxshop_order_food ofd on o.id = ofd.order_id left join wxshop_food f on f.id = ofd.food_id where o.user_id = #{userId} and o.is_pay = 1
and o.id < #{lastId}
order by o.id desc limit #{size}

select id, user_id, price, promotion, number, is_pay, is_taken, comment, create_time, pay_time, taken_time from wxshop_order where user_id = #{userId} and is_pay = 1
and id < #{lastId}
order by id desc limit #{size}
